import type { QuestionType } from './question';

/**
 * Option payload within an AI-generated question.
 */
export interface AiGeneratedOptionDto {
  orderIndex: number;
  content: string;
  isCorrect: boolean;
  imageUrl?: string | null;
}

/**
 * Individual question structured and generated by Gemini AI from documents.
 */
export interface AiGeneratedQuestionDto {
  id?: string;
  orderIndex?: number;
  content: string;
  questionType: QuestionType;
  points: number;
  explanation?: string | null;
  difficulty?: 'EASY' | 'MEDIUM' | 'HARD' | string | null;
  sampleAnswer?: string | null;
  gradingRubric?: string | null;
  numericTolerance?: number | null;
  options: AiGeneratedOptionDto[];
}

/**
 * Configuration payload submitted to start AI document analysis and question generation.
 */
export interface AiGenerateQuizRequest {
  examId?: string;
  totalQuestions?: number;
  difficulty?: 'BALANCED' | 'EASY' | 'MEDIUM' | 'HARD' | string;
  language?: 'vi' | 'en' | string;
  rawText?: string;
  additionalInstructions?: string;
  targetQuestionTypes?: QuestionType[];
}

/**
 * Real-time status and snapshot of an AI generation job in the single-thread queue.
 */
export interface AiGenerateJobResponse {
  jobId: string;
  fileName: string;
  status: 'QUEUED' | 'PROCESSING' | 'COMPLETED' | 'FAILED' | 'CANCELLED';
  progressPercent: number;
  message: string;
  questions?: AiGeneratedQuestionDto[];
  error?: string | null;
  createdAt?: string;
  updatedAt?: string;
}

/**
 * Bulk commit payload for adding selected AI-generated questions into an exam.
 */
export interface AiCommitQuestionsRequest {
  questions: AiGeneratedQuestionDto[];
}
